import regex, strutils, tables
from futhark import SymbolKind

const default_prefix = """
# This was generated by futhark, and should not be edited directly.

"""


const commentRe = re2(r"\s*## Generated based on .+$", {regexMultiline})

proc processWrapperFile*(path: string, prefix: string = default_prefix) =
    var content = readFile(path)
    content = content.replace(commentRe, "")

    let outF = open(path, fmWrite)
    defer: outF.close

    outF.write(prefix & content)


proc fixStaticConsts*(path: string) =
    ## futhark emits static const C objects as uninitialized Nim vars.
    const replacements = {
        "b2Vec2_zero": "const b2Vec2_zero*: b2Vec2 = b2Vec2(x: 0.0f, y: 0.0f)",
        "b2Rot_identity": "const b2Rot_identity*: b2Rot = b2Rot(c: 1.0f, s: 0.0f)",
        "b2Transform_identity": "const b2Transform_identity*: b2Transform = b2Transform(p: b2Vec2_zero, q: b2Rot_identity)",
        "b2Mat22_zero": "const b2Mat22_zero*: b2Mat22 = b2Mat22(cx: b2Vec2_zero, cy: b2Vec2_zero)",
        "b2Pos_zero": "const b2Pos_zero*: b2Pos = b2Pos(x: 0.0f, y: 0.0f)",
        "b2WorldTransform_identity": "const b2WorldTransform_identity*: b2WorldTransform = b2WorldTransform(p: b2Pos_zero, q: b2Rot_identity)",
        "b2_nullWorldId": "const b2_nullWorldId*: b2WorldId = b2WorldId(index1: 0, generation: 0)",
        "b2_nullBodyId": "const b2_nullBodyId*: b2BodyId = b2BodyId(index1: 0, world0: 0, generation: 0)",
        "b2_nullShapeId": "const b2_nullShapeId*: b2ShapeId = b2ShapeId(index1: 0, world0: 0, generation: 0)",
        "b2_nullChainId": "const b2_nullChainId*: b2ChainId = b2ChainId(index1: 0, world0: 0, generation: 0)",
        "b2_nullJointId": "const b2_nullJointId*: b2JointId = b2JointId(index1: 0, world0: 0, generation: 0)",
        "b2_nullContactId": "const b2_nullContactId*: b2ContactId = b2ContactId(index1: 0, world0: 0, padding: 0, generation: 0)",
        "b2_emptySimplexCache": "const b2_emptySimplexCache*: b2SimplexCache = b2SimplexCache()",
    }.toTable

    var lines = readFile(path).splitLines()
    for i, line in lines:
        let stripped = line.strip()
        for name, replacement in replacements:
            if stripped.startsWith("var " & name & "*:"):
                let indent = line[0 ..< line.len - line.strip(leading = true, trailing = false).len]
                lines[i] = indent & replacement
                break

    writeFile(path, lines.join("\n"))


proc wrapperRenameCallback*(name: string, kind: SymbolKind, partof = "", overloading: var bool): string =
    result = name
    if name == "type":
        result = "bodyType"
